const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const fwd = (f) => V(Math.sin(f.yaw), 0, Math.cos(f.yaw));
const chest = (f, h = 1.3) => V(f.pos.x, f.pos.y + h, f.pos.z);
const flat = (a, b) => Math.hypot(a.x - b.x, a.z - b.z);
const keep = (o) => { o.userData.keepGeo = false; return o; };

export const RARITY = {
  C: { name: 'Common', color: '#b8c0cc', w: 74, refund: 30 },
  R: { name: 'Rare', color: '#4fa8ff', w: 19, refund: 60 },
  E: { name: 'Epic', color: '#b366ff', w: 5.5, refund: 120 },
  L: { name: 'Legendary', color: '#ffb43c', w: 1.5, refund: 250 },
};
export const SLOTS = { p: 'Passive', a: 'Active', s: 'Shikigami', u: 'Ultimate State', d: 'Domain', f: 'Fighting Style', p2: 'Passive 2' };
export const BOX_COST = { a: 300, p: 300, s: 300, u: 700, d: 1600, f: 400 };
export const DOMAIN_HIT = 0.22; // chance a Domain Box holds a domain at all

function aimPoint(f, range = 10) {
  if (f.target && !f.target.dead) return { pos: f.target.pos.clone(), target: f.target };
  return { pos: f.pos.clone().addScaledVector(fwd(f), range), target: null };
}
function pulseWarn(G, pos, r, color, t) { G.fx.ring(pos.clone().setY(0.1), color, r * 0.3, r, t); G.fx.ring(pos.clone().setY(0.1), color, r, r * 0.95, t); }
function domeMesh(R, color, kind) {
  let m;
  if (kind === 'void') { m = makeSky('#000004', '#2a0f5a', V(0, 1, 0), '#8a6aff', true); m.scale.setScalar(R / 400); m.material.side = THREE.BackSide; m.material.transparent = true; m.material.opacity = 0.97; m.renderOrder = 5; m.userData.own = true; return m; }
  const mat = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    uniforms: { c: { value: new THREE.Color(color).multiplyScalar(1.6) }, t: { value: 0 }, a: { value: 1 } },
    vertexShader: 'varying vec3 vN; varying vec3 vP; void main(){ vN=normalize(normalMatrix*normal); vP=position; vec4 mv=modelViewMatrix*vec4(position,1.0); gl_Position=projectionMatrix*mv; }',
    fragmentShader: `varying vec3 vN; varying vec3 vP; uniform vec3 c; uniform float t,a; void main(){ float f=pow(1.0-abs(vN.z),2.2); float g=0.5+0.5*sin(vP.y*1.8+t*3.0+sin(vP.x*1.3+t)*2.0); gl_FragColor=vec4(c*(0.25+f*1.4)*(0.7+0.5*g), (0.05+f*0.4)*a); }`,
  });
  m = new THREE.Mesh(new THREE.SphereGeometry(R, 48, 32), mat); m.renderOrder = 4; return m;
}

