/* ================= SHIKIGAMI ================= */
function critter(color, big = 1, kind = 'dog') {
  const g = new THREE.Group(); const m = new THREE.MeshStandardMaterial({ color, roughness: 0.7 });
  const b = (w, h, d, x, y, z) => { const me = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); me.position.set(x, y, z); me.castShadow = true; g.add(me); return me; };
  if (kind === 'dog') { b(0.6, 0.6, 1.3, 0, 0.7, 0); b(0.5, 0.5, 0.55, 0, 0.95, 0.8); b(0.2, 0.3, 0.1, 0.15, 1.3, 0.8); b(0.2, 0.3, 0.1, -0.15, 1.3, 0.8); for (const x of [-0.2, 0.2]) for (const z of [-0.45, 0.45]) b(0.16, 0.5, 0.16, x, 0.25, z); }
  if (kind === 'rabbit') { b(0.45, 0.4, 0.7, 0, 0.3, 0); b(0.34, 0.34, 0.34, 0, 0.5, 0.42); b(0.1, 0.5, 0.1, 0.08, 0.95, 0.4); b(0.1, 0.5, 0.1, -0.08, 0.95, 0.4); }
  if (kind === 'bird') { b(0.8, 0.7, 1.6, 0, 0, 0); b(0.5, 0.5, 0.5, 0, 0.3, 0.95); const w1 = b(3.2, 0.12, 1.0, 0, 0.2, 0), w2 = b(3.2, 0.12, 1.0, 0, 0.2, 0); g.userData.wings = [w1]; b(0.3, 0.3, 1.4, 0, 0, -1.4); const em = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.1, 0.1), new THREE.MeshBasicMaterial({ color: new THREE.Color('#8fb8ff').multiplyScalar(3), toneMapped: false })); g.add(em); }
  g.scale.setScalar(big); return g;
}
